    <!-- Initialize Swiper -->
    <script>
        // Initialize first Swiper
        var swiper1 = new Swiper('.firstSwiper', {
            spaceBetween: 30,
            grabCursor: true,
            loop: true,
            pagination: {
                el: ".swiper-pagination",
                clickable: true,
            },
            navigation: {
                nextEl: ".first-next",
                prevEl: ".first-prev",
            },
            breakpoints: {
                0: {
                    slidesPerView: 1
                },
                768: {
                    slidesPerView: 2
                },
                1024: {
                    slidesPerView: 3
                },
                1150: {
                    slidesPerView: 4
                },
                1600: {
                    slidesPerView: 5
                }
            }
        });

        // Initialize second Swiper
        var swiper2 = new Swiper('.secondSwiper', {
            spaceBetween: 30,
            grabCursor: true,
            loop: true,
            pagination: {
                el: ".swiper-pagination",
                clickable: true,
            },
            navigation: {
                nextEl: ".second-next",
                prevEl: ".second-prev",
            },
            breakpoints: {
                0: {
                    slidesPerView: 1
                },
                768: {
                    slidesPerView: 2
                },
                1024: {
                    slidesPerView: 3
                },
                1150: {
                    slidesPerView: 4
                },
                1600: {
                    slidesPerView: 5
                }
            }
        });
    </script>

    <script>
        const buttons = document.querySelectorAll('.uno a');

        const allSections = document.querySelectorAll('.form-section');

        buttons.forEach(function(btn) {
            btn.addEventListener('click', function(e) {
                e.preventDefault();
                const targetId = btn.getAttribute('data-target');
                const targetSection = document.getElementById(targetId);


                allSections.forEach(function(section) {
                    section.classList.remove('show-form');
                });
                if (targetSection) {
                    targetSection.classList.toggle('show-form');
                }
            });
        });
    </script>
